# proto.py
def handle(line):
    teile = line.split()
    if not teile:
        return "ERR leer"
    cmd, args = teile[0].upper(), teile[1:]
    if cmd == "ADD" and len(args) == 2:
        try:
            a, b = int(args[0]), int(args[1])
        except ValueError:
            return "ERR keine Zahl"
        return f"OK {a + b}"
    if cmd == "PING":
        return "OK PONG"
    return "ERR unbekannt"

using System.Net;
using System.Net.Sockets;
using System.Text;

var listener = new TcpListener(
    IPAddress.Loopback, 5002);
listener.Start();
Task server = Task.Run(async () =>
{
    using TcpClient c =
        await listener.AcceptTcpClientAsync();
    NetworkStream s = c.GetStream();
    byte[] buf = new byte[1024];
    int n;
    while ((n = await s.ReadAsync(buf)) > 0)
        await s.WriteAsync(buf.AsMemory(0, n));
});

// Client (hier im selben Programm)
using (var client = new TcpClient())
{
    await client.ConnectAsync("127.0.0.1", 5002);
    var st = client.GetStream();
    await st.WriteAsync(
        Encoding.UTF8.GetBytes("Hallo HTL"));
    byte[] buf = new byte[1024];
    int n = await st.ReadAsync(buf);
    Console.WriteLine("Echo: " +
        Encoding.UTF8.GetString(buf, 0, n));
}
await server;
listener.Stop();

// Ausgabe: Echo: Hallo HTL
